def cargar(apps, schema_editor):
    m = lambda nombre: apps.get_model(APP, nombre)
    Sector, Programa, Producto, Indicador = (m("SectorCatalogo"), m("ProgramaCatalogo"),
                                             m("ProductoCatalogo"), m("IndicadorCatalogo"))
    Medido, Unidad = m("MedidoATravesDe"), m("UnidadMedida")

    Sector.objects.bulk_create([Sector(codigo=c, nombre=n) for c, n in SECTORES])
    sectores = dict(Sector.objects.values_list("codigo", "pk"))
    Programa.objects.bulk_create([Programa(codigo=c, sector_id=sectores[s], nombre=n) for c, s, n in PROGRAMAS])
    programas = dict(Programa.objects.values_list("codigo", "pk"))

    medidos = {n: Medido.objects.get_or_create(nombre=n)[0].pk for n in sorted({p[4] for p in PRODUCTOS if p[4]})}
    Producto.objects.bulk_create([
        Producto(codigo=c, programa_id=programas[pr], nombre=n, descripcion=d, medido_a_traves_de_id=medidos.get(md))
        for c, pr, n, d, md in PRODUCTOS], batch_size=500)
    productos = dict(Producto.objects.values_list("codigo", "pk"))

    unidades = {n: Unidad.objects.get_or_create(nombre=n)[0].pk for n in sorted({i[3] for i in INDICADORES if i[3]})}
    Indicador.objects.bulk_create([
        Indicador(codigo=c, producto_id=productos[p], nombre=n, unidad_medida_id=unidades.get(u),
                  es_principal=pr, es_nacional=na, es_territorial=te)
        for c, p, n, u, pr, na, te in INDICADORES], batch_size=500)

    # Homologacion por codigo con los indicadores del plan
    catalogo = dict(Indicador.objects.values_list("codigo", "pk"))
    Homologacion = m("HomologacionIndicador")
